2.25.1

### Modifications in Each File

1. **File: `net/core/rtnetlink.c`**
   - The code block that enslaved a device before bringing it up has been removed. Specifically, the following lines were deleted:
     ```c
     if (tb[IFLA_MASTER]) {
         err = do_set_master(dev, nla_get_u32(tb[IFLA_MASTER]), extack);
         if (err)
             goto errout;
         status |= DO_SETLINK_MODIFIED;
     }
     ```
   - The same block of code has been re-added later in the function, after the flags are processed, effectively changing the order of operations.

### Relationships Between Modifications

- The patch reverts a previous change that enforced enslaving a device before it could be brought up. This change was problematic as it broke the ability to enslave an interface with a single netlink message when the device was already up. 
- The modification restores the original behavior, allowing the enslaving operation to occur after the device's flags have been processed, thus maintaining the functionality of commands like `ip link set dummy0 master bond0 down`.
- The decision to revert was based on discussions indicating that there was no compelling reason to require the device to be down before it could be enslaved, especially since the bond interface would automatically set the slave up when it is up.

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Revert "net: rtnetlink: Enslave device before bringing it up"

This reverts commit a4abfa627c3865c37e036bccb681619a50d3d93c.

The patch broke:
> ip link set dummy0 up
> ip link set dummy0 master bond0 down

This last command is useful to be able to enslave an interface with only
one netlink message.

After discussion, there is no good reason to support:
> ip link set dummy0 down
> ip link set dummy0 master bond0 up
because the bond interface already set the slave up when it is up.

Cc: stable@vger.kernel.org
Fixes: a4abfa627c38 ("net: rtnetlink: Enslave device before bringing it up")
Signed-off-by: Nicolas Dichtel <nicolas.dichtel@6wind.com>
Reviewed-by: Jiri Pirko <jiri@nvidia.com>
Reviewed-by: Hangbin Liu <liuhangbin@gmail.com>
Link: https://lore.kernel.org/r/20240108094103.2001224-2-nicolas.dichtel@6wind.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug was caused by the enforcement of enslaving a device before it could be brought up, which broke the functionality of enslaving an interface with a single netlink message when the device was already up. This restriction was unnecessary since the bond interface would automatically set the slave up when it is up, leading to confusion and limitations in the expected behavior of network commands.

Here is the patch:
 #define DO_SETLINK_NOTIFY	0x03
 static int do_setlink(const struct sk_buff *skb,
 		      struct net_device *dev, struct ifinfomsg *ifm,
 		      struct netlink_ext_ack *extack,
 		      struct nlattr **tb, int status)
 {
 	const struct net_device_ops *ops = dev->netdev_ops;
 	char ifname[IFNAMSIZ];
 	int err;

 	if (tb[IFLA_IFNAME])
 		nla_strscpy(ifname, tb[IFLA_IFNAME], IFNAMSIZ);
 	else
 		ifname[0] = '\0';

 	if (tb[IFLA_NET_NS_PID] || tb[IFLA_NET_NS_FD] || tb[IFLA_TARGET_NETNSID]) {
 		const char *pat = ifname[0] ? ifname : NULL;
 		struct net *net;
 		int new_ifindex;

 		net = rtnl_link_get_net_capable(skb, dev_net(dev),
 						tb, CAP_NET_ADMIN);
 		if (IS_ERR(net)) {
 			err = PTR_ERR(net);
 			goto errout;
 		}

 		if (tb[IFLA_NEW_IFINDEX])
 			new_ifindex = nla_get_s32(tb[IFLA_NEW_IFINDEX]);
 		else
 			new_ifindex = 0;

 		err = __dev_change_net_namespace(dev, net, pat, new_ifindex);
 		put_net(net);
 		if (err)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_MAP]) {
 		struct rtnl_link_ifmap *u_map;
 		struct ifmap k_map;

 		if (!ops->ndo_set_config) {
 			err = -EOPNOTSUPP;
 			goto errout;
 		}

 		if (!netif_device_present(dev)) {
 			err = -ENODEV;
 			goto errout;
 		}

 		u_map = nla_data(tb[IFLA_MAP]);
 		k_map.mem_start = (unsigned long) u_map->mem_start;
 		k_map.mem_end = (unsigned long) u_map->mem_end;
 		k_map.base_addr = (unsigned short) u_map->base_addr;
 		k_map.irq = (unsigned char) u_map->irq;
 		k_map.dma = (unsigned char) u_map->dma;
 		k_map.port = (unsigned char) u_map->port;

 		err = ops->ndo_set_config(dev, &k_map);
 		if (err < 0)
 			goto errout;

 		status |= DO_SETLINK_NOTIFY;
 	}

 	if (tb[IFLA_ADDRESS]) {
 		struct sockaddr *sa;
 		int len;

 		len = sizeof(sa_family_t) + max_t(size_t, dev->addr_len,
 						  sizeof(*sa));
 		sa = kmalloc(len, GFP_KERNEL);
 		if (!sa) {
 			err = -ENOMEM;
 			goto errout;
 		}
 		sa->sa_family = dev->type;
 		memcpy(sa->sa_data, nla_data(tb[IFLA_ADDRESS]),
 		       dev->addr_len);
 		err = dev_set_mac_address_user(dev, sa, extack);
 		kfree(sa);
 		if (err)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_MTU]) {
 		err = dev_set_mtu_ext(dev, nla_get_u32(tb[IFLA_MTU]), extack);
 		if (err < 0)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_GROUP]) {
 		dev_set_group(dev, nla_get_u32(tb[IFLA_GROUP]));
 		status |= DO_SETLINK_NOTIFY;
 	}

 	/*
 	 * Interface selected by interface index but interface
 	 * name provided implies that a name change has been
 	 * requested.
 	 */
 	if (ifm->ifi_index > 0 && ifname[0]) {
 		err = dev_change_name(dev, ifname);
 		if (err < 0)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_IFALIAS]) {
 		err = dev_set_alias(dev, nla_data(tb[IFLA_IFALIAS]),
 				    nla_len(tb[IFLA_IFALIAS]));
 		if (err < 0)
 			goto errout;
 		status |= DO_SETLINK_NOTIFY;
 	}

 	if (tb[IFLA_BROADCAST]) {
 		nla_memcpy(dev->broadcast, tb[IFLA_BROADCAST], dev->addr_len);
 		call_netdevice_notifiers(NETDEV_CHANGEADDR, dev);
 	}

-	if (tb[IFLA_MASTER]) {
-		err = do_set_master(dev, nla_get_u32(tb[IFLA_MASTER]), extack);
-		if (err)
-			goto errout;
-		status |= DO_SETLINK_MODIFIED;
-	}
-
 	if (ifm->ifi_flags || ifm->ifi_change) {
 		err = dev_change_flags(dev, rtnl_dev_combine_flags(dev, ifm),
 				       extack);
 		if (err < 0)
 			goto errout;
 	}

+	if (tb[IFLA_MASTER]) {
+		err = do_set_master(dev, nla_get_u32(tb[IFLA_MASTER]), extack);
+		if (err)
+			goto errout;
+		status |= DO_SETLINK_MODIFIED;
+	}
+
 	if (tb[IFLA_CARRIER]) {
 		err = dev_change_carrier(dev, nla_get_u8(tb[IFLA_CARRIER]));
 		if (err)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_TXQLEN]) {
 		unsigned int value = nla_get_u32(tb[IFLA_TXQLEN]);

 		err = dev_change_tx_queue_len(dev, value);
 		if (err)
 			goto errout;
 		status |= DO_SETLINK_MODIFIED;
 	}

 	if (tb[IFLA_GSO_MAX_SIZE]) {
 		u32 max_size = nla_get_u32(tb[IFLA_GSO_MAX_SIZE]);

 		if (dev->gso_max_size ^ max_size) {
 			netif_set_gso_max_size(dev, max_size);
 			status |= DO_SETLINK_MODIFIED;
 		}
 	}

 	if (tb[IFLA_GSO_MAX_SEGS]) {
 		u32 max_segs = nla_get_u32(tb[IFLA_GSO_MAX_SEGS]);

 		if (dev->gso_max_segs ^ max_segs) {
 			netif_set_gso_max_segs(dev, max_segs);
 			status |= DO_SETLINK_MODIFIED;
 		}
 	}

 	if (tb[IFLA_GRO_MAX_SIZE]) {
 		u32 gro_max_size = nla_get_u32(tb[IFLA_GRO_MAX_SIZE]);

 		if (dev->gro_max_size ^ gro_max_size) {
 			netif_set_gro_max_size(dev, gro_max_size);
 			status |= DO_SETLINK_MODIFIED;
 		}
 	}

 	if (tb[IFLA_GSO_IPV4_MAX_SIZE]) {
 		u32 max_size = nla_get_u32(tb[IFLA_GSO_IPV4_MAX_SIZE]);

 		if (dev->gso_ipv4_max_size ^ max_size) {
 			netif_set_gso_ipv4_max_size(dev, max_size);
 			status |= DO_SETLINK_MODIFIED;
 		}
 	}

 	if (tb[IFLA_GRO_IPV4_MAX_SIZE]) {
 		u32 gro_max_size = nla_get_u32(tb[IFLA_GRO_IPV4_MAX_SIZE]);

 		if (dev->gro_ipv4_max_size ^ gro_max_size) {
 			netif_set_gro_ipv4_max_size(dev, gro_max_size);
 			status |= DO_SETLINK_MODIFIED;
 		}
 	}

 	if (tb[IFLA_OPERSTATE])
 		set_operstate(dev, nla_get_u8(tb[IFLA_OPERSTATE]));

 	if (tb[IFLA_LINKMODE]) {
 		unsigned char value = nla_get_u8(tb[IFLA_LINKMODE]);

 		write_lock(&dev_base_lock);
 		if (dev->link_mode ^ value)
 			status |= DO_SETLINK_NOTIFY;
 		dev->link_mode = value;
 		write_unlock(&dev_base_lock);
 	}

 	if (tb[IFLA_VFINFO_LIST]) {
 		struct nlattr *vfinfo[IFLA_VF_MAX + 1];
 		struct nlattr *attr;
 		int rem;

 		nla_for_each_nested(attr, tb[IFLA_VFINFO_LIST], rem) {
 			if (nla_type(attr) != IFLA_VF_INFO ||
 			    nla_len(attr) < NLA_HDRLEN) {
 				err = -EINVAL;
 				goto errout;
 			}
 			err = nla_parse_nested_deprecated(vfinfo, IFLA_VF_MAX,
 							  attr,
 							  ifla_vf_policy,
 							  NULL);
 			if (err < 0)
 				goto errout;
 			err = do_setvfinfo(dev, vfinfo);
 			if (err < 0)
 				goto errout;
 			status |= DO_SETLINK_NOTIFY;
 		}
 	}
 	err = 0;

 	if (tb[IFLA_VF_PORTS]) {
 		struct nlattr *port[IFLA_PORT_MAX+1];
 		struct nlattr *attr;
 		int vf;
 		int rem;

 		err = -EOPNOTSUPP;
 		if (!ops->ndo_set_vf_port)
 			goto errout;

 		nla_for_each_nested(attr, tb[IFLA_VF_PORTS], rem) {
 			if (nla_type(attr) != IFLA_VF_PORT ||
 			    nla_len(attr) < NLA_HDRLEN) {
 				err = -EINVAL;
 				goto errout;
 			}
 			err = nla_parse_nested_deprecated(port, IFLA_PORT_MAX,
 							  attr,
 							  ifla_port_policy,
 							  NULL);
 			if (err < 0)
 				goto errout;
 			if (!port[IFLA_PORT_VF]) {
 				err = -EOPNOTSUPP;
 				goto errout;
 			}
 			vf = nla_get_u32(port[IFLA_PORT_VF]);
 			err = ops->ndo_set_vf_port(dev, vf, port);
 			if (err < 0)
 				goto errout;
 			status |= DO_SETLINK_NOTIFY;
 		}
 	}
 	err = 0;

 	if (tb[IFLA_PORT_SELF]) {
 		struct nlattr *port[IFLA_PORT_MAX+1];

 		err = nla_parse_nested_deprecated(port, IFLA_PORT_MAX,
 						  tb[IFLA_PORT_SELF],
 						  ifla_port_policy, NULL);
 		if (err < 0)
 			goto errout;

 		err = -EOPNOTSUPP;
 		if (ops->ndo_set_vf_port)
 			err = ops->ndo_set_vf_port(dev, PORT_SELF_VF, port);
 		if (err < 0)
 			goto errout;
 		status |= DO_SETLINK_NOTIFY;
 	}

 	if (tb[IFLA_AF_SPEC]) {
 		struct nlattr *af;
 		int rem;

 		nla_for_each_nested(af, tb[IFLA_AF_SPEC], rem) {
 			const struct rtnl_af_ops *af_ops;

 			BUG_ON(!(af_ops = rtnl_af_lookup(nla_type(af))));

 			err = af_ops->set_link_af(dev, af, extack);
 			if (err < 0)
 				goto errout;

 			status |= DO_SETLINK_NOTIFY;
 		}
 	}
 	err = 0;

 	if (tb[IFLA_PROTO_DOWN] || tb[IFLA_PROTO_DOWN_REASON]) {
 		err = do_set_proto_down(dev, tb[IFLA_PROTO_DOWN],
 					tb[IFLA_PROTO_DOWN_REASON], extack);
 		if (err)
 			goto errout;
 		status |= DO_SETLINK_NOTIFY;
 	}

 	if (tb[IFLA_XDP]) {
 		struct nlattr *xdp[IFLA_XDP_MAX + 1];
 		u32 xdp_flags = 0;

 		err = nla_parse_nested_deprecated(xdp, IFLA_XDP_MAX,
 						  tb[IFLA_XDP],
 						  ifla_xdp_policy, NULL);
 		if (err < 0)
 			goto errout;

 		if (xdp[IFLA_XDP_ATTACHED] || xdp[IFLA_XDP_PROG_ID]) {
 			err = -EINVAL;
 			goto errout;
 		}

 		if (xdp[IFLA_XDP_FLAGS]) {
 			xdp_flags = nla_get_u32(xdp[IFLA_XDP_FLAGS]);
 			if (xdp_flags & ~XDP_FLAGS_MASK) {
 				err = -EINVAL;
 				goto errout;
 			}
 			if (hweight32(xdp_flags & XDP_FLAGS_MODES) > 1) {
 				err = -EINVAL;
 				goto errout;
 			}
 		}

 		if (xdp[IFLA_XDP_FD]) {
 			int expected_fd = -1;

 			if (xdp_flags & XDP_FLAGS_REPLACE) {
 				if (!xdp[IFLA_XDP_EXPECTED_FD]) {
 					err = -EINVAL;
 					goto errout;
 				}
 				expected_fd =
 					nla_get_s32(xdp[IFLA_XDP_EXPECTED_FD]);
 			}

 			err = dev_change_xdp_fd(dev, extack,
 						nla_get_s32(xdp[IFLA_XDP_FD]),
 						expected_fd,
 						xdp_flags);
 			if (err)
 				goto errout;
 			status |= DO_SETLINK_NOTIFY;
 		}
 	}

 errout:
 	if (status & DO_SETLINK_MODIFIED) {
 		if ((status & DO_SETLINK_NOTIFY) == DO_SETLINK_NOTIFY)
 			netdev_state_change(dev);

 		if (err < 0)
 			net_warn_ratelimited("A link change request failed with some changes committed already. Interface %s may have been left with an inconsistent configuration, please check.\n",
 					     dev->name);
 	}

 	return err;
 }



